const D = { density:.55, energy:.65, hue:24, speed:1, scale:1, x:.5, y:1, spread:.7, wiggle:.6, style:'ember', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const clp=(v,a,b)=>Math.max(a,Math.min(b,v));
const frc=v=>v-Math.floor(v);
const md=(a,n)=>((a%n)+n)%n;
const lrp=(a,b,t)=>a+(b-a)*t;
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};

const W=width,Hh=height,u=Math.min(W,Hh);
const H=md(P.hue,360);
const st=P.style;
const ember=st==='ember',thermal=st==='thermal',spark=st==='spark',sumi=st==='sumi',ascii=st==='ascii';

const en=clp(P.energy,0,1);
const nE=Math.round(lrp(36,190,clp(P.density,0,1)));
const rise=(0.10+en*0.14)*P.speed;
const baseX=P.x*W;
const baseY=P.y*Hh;
const spread=clp(P.spread,0,1)*W*0.55;
const wig=0.4+P.wiggle*2.2;
// bass gust scatter (blended over baseline)
const gustX=(A.bass-0.15)*u*0.18 + Math.sin(K.t*0.4)*u*0.02;
const beatFlare=1+K.pulse*0.3*en+A.bass*0.35;

const glyphs=' .:-=+coO*#';

// cooling color over normalized life f (0 hot base -> 1 cold top)
function heatCol(f){
  if(thermal){ return [md(H+lrp(50,255,f),360), lrp(30,92,f), lrp(100,70,1-f*0.4)]; }
  if(sumi){ return [md(H,360), 6, lrp(72,26,f)]; }
  if(spark){ return f<0.25? [md(H+22,360),12,100] : [md(H+lrp(30,-10,f),360), lrp(70,96,f), lrp(100,74,f)]; }
  // ember: yellow-white hot -> orange -> deep red -> ash
  const h=md(H+lrp(24,-16,f),360);
  return [h, lrp(55,98,clp(f*1.3,0,1)), lrp(100,52,f)];
}

if(ascii) textAlign(CENTER,CENTER);
const addBlend = ember||thermal||spark;
if(addBlend) blendMode(ADD); else blendMode(BLEND);
noStroke();

for(let i=0;i<nE;i++){
  const sd=i+1;
  const spd=0.55+fr(sd*2)*1.0;
  const life=frc(fr(sd*3) + K.t*rise*spd);           // continuous rise
  const f=life;                                       // cooling factor
  // heat-wiggle horizontal, real-time
  const wx=Math.sin(K.t*(1.4+spd*1.2)*wig + fr(sd*5)*6.28)*u*0.03*(0.5+life*1.4);
  const lane=(fr(sd*7)-0.5);
  const ex=baseX + lane*spread*(0.4+life*0.9) + wx + gustX*life*(0.5+fr(sd*11));
  const ey=baseY - life*(Hh*0.98) - u*0.01;
  const fade=Math.sin(life*Math.PI);                 // fade in at base, out at top
  const sz=u*(0.0035+0.006*fr(sd*13))*P.scale*(1-life*0.35)*beatFlare*(0.7+en*0.6);
  const col=heatCol(f);
  const a=clp(fade*(thermal?68:88)*(0.5+en*0.6),0,100);

  if(ascii){
    const gi=Math.min(glyphs.length-1, Math.floor((1-f)*(glyphs.length-1)));
    const g=glyphs[gi];
    if(g!==' '){ fill(col[0],col[1],col[2], a); textSize(Math.max(5,sz*3.2)); text(g,ex,ey); }
  } else if(spark){
    // hot core + short vertical trail
    fill(col[0],col[1],col[2], a); ellipse(ex,ey,sz*1.3,sz*1.3);
    fill(col[0],clp(col[1]-30,0,100),100, a*0.5); ellipse(ex,ey+sz*2.2,sz*0.7,sz*3.2);
  } else if(sumi){
    // ash flecks: soft grey specks, BLEND
    fill(col[0],col[1],col[2], a*0.9); ellipse(ex,ey,sz*1.1,sz*1.1);
  } else {
    // ember/thermal glowing dot with soft halo
    fill(col[0],clp(col[1]-18,0,100),clp(col[2]+6,0,100), a*0.5); ellipse(ex,ey,sz*2.6,sz*2.6);
    fill(col[0],col[1],col[2], a); ellipse(ex,ey,sz*1.2,sz*1.2);
  }
}

// base heat glow at source (breathes on beat), skip for sumi
if(!sumi){
  blendMode(ADD); noStroke();
  const gb=(0.4+en*0.6+K.swell*0.25+A.bass*0.4);
  const gr=spread*(0.7+0.1*Math.sin(K.t*2.3));
  for(let r=6;r>0;r--){ const t=r/6; const gc=heatCol(0.08); fill(gc[0],gc[1],gc[2], 6*gb*(1-t)*(1-t)); ellipse(baseX,baseY,gr*t*2,gr*t*0.7); }
}

blendMode(BLEND);
drawingContext.shadowBlur=0;
